import{_ as e,o as i,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2018-JAN-18 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2018-JAN-18 :: Ceph Performance Weekly","date":"2018-01-20T00:00:00.000Z","updated":"2018-01-20T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","VPP集成","Specter漏洞"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-JAN-18_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2018/2018-JAN-18_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),t={name:"posts/2018/2018-JAN-18_-_-_Ceph_Performance_Weekly.md"};function a(n,l,s,p,u,P){return i(),r("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Ron, Adam, Jason, Igor, Josh, Greg, Mark, Chimay, Stephanie, Avi, Georgia, 以及其他相关人员</p><p><strong>会议主题</strong>：</p><ul><li>Ceph 存储系统最新进展</li><li>VPP 集成方案探讨</li><li>性能优化策略讨论</li><li>Specter 漏洞影响评估</li></ul><h3 id="会议内容" tabindex="-1">会议内容： <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容：&quot;">​</a></h3><p><strong>1. Ceph 存储系统最新进展</strong></p><ul><li><strong>代码合并与优化</strong>： <ul><li>Jason 审核并合并了 Igor 的几个小优化，包括近似眼睛（aprox eyes）功能。</li><li>Jason 还合并了一个 pull request，该 pull request 通过优化读取操作来提高性能。</li><li>Ron 考虑完全消除对象存储接口中的 applied 回调，并使用跟踪和快速操作。</li><li>Ron 关闭了旧的同步请求，因为他已经完成了读操作的一半工作，但不确定是否要继续进行写操作。</li></ul></li><li><strong>性能优化</strong>： <ul><li>Ron 考虑使用构建购买概念来测试性能影响。</li><li>Josh 提交了一个 pull request，用于将随机拆分阈值随机化，以提高 Jewel 版本的性能。</li><li>Ron 提到了一个 QAT 等级类，但不确定其最新更新。</li></ul></li></ul><p><strong>2. VPP 集成方案探讨</strong></p><ul><li><strong>VPP 简介</strong>： <ul><li>Stephanie 介绍了 VPP（虚拟包处理）软件栈，该软件栈提供了一种高效的网络处理方式。</li><li>VPP 支持多种接口，包括 VPP 通信库、TCL API 和 DPDK 内存接口。</li><li>Stephanie 使用了预加载模式，即 VPP 库钩子到 POSIX 套接字层，从而在用户空间中处理网络操作。</li></ul></li><li><strong>集成方案讨论</strong>： <ul><li>Ron 认为直接使用 VPP API 可能更合适，因为它可以提供更好的性能和异步操作。</li><li>讨论了 VPP 与 CStar 网络编程框架的兼容性，以及如何使用 CStar API 与 VPP 通信。</li><li>讨论了将 VPP 作为 RGW 插件的可能性。</li></ul></li></ul><p><strong>3. 性能优化策略讨论</strong></p><ul><li><strong>Boost 优化</strong>： <ul><li>Mark 总结了 Boost 优化方案的测试结果，发现一些优化方案对性能提升有限，例如批处理事务和跳表。</li><li>Ron 认为使用多个提示符（hints）的 RocksDB 内部功能可能有助于提高性能，但需要进一步测试。</li></ul></li><li><strong>Specter 漏洞影响评估</strong>： <ul><li>Ron 认为 Specter 漏洞可能会对 Intel 处理器的性能产生严重影响，尤其是在进行大量 CPU 密集型操作时。</li><li>Red Hat 性能团队正在研究 Specter 漏洞的解决方案。</li></ul></li></ul><p><strong>4. 其他讨论</strong></p><ul><li><strong>Wall Clock Profiler</strong>： <ul><li>Adam 介绍了 Wall Clock Profiler 工具，该工具可以模拟 Marc 的 Wall Clock Profiler 的行为，并提供更快的采样率。</li><li>Adam 还表示，他愿意将 Wall Clock Profiler 集成到 CBT 中，以便在测试过程中进行性能分析。</li></ul></li><li><strong>New Store 与 Blue Store 比较</strong>： <ul><li>Ron 回顾了 New Store 和 Blue Store 的性能比较，发现 Blue Store 在大写和随机写操作方面表现更好。</li><li>Ron 认为读取预取在 Blue Store 中非常重要。</li></ul></li><li><strong>EC Bug Regression</strong>： <ul><li>Ron 讨论了对象存储层中未读回调的问题，并提出了一种简化代码的方案。</li></ul></li></ul><h3 id="行动计划" tabindex="-1">行动计划： <a class="header-anchor" href="#行动计划" aria-label="Permalink to &quot;行动计划：&quot;">​</a></h3><ul><li><strong>VPP 集成</strong>： <ul><li>与 Avi 和 Georgia 讨论将 VPP 集成到 Ceph 的可能性。</li><li>对 VPP 进行性能测试，并评估其与 CStar 的兼容性。</li></ul></li><li><strong>性能优化</strong>： <ul><li>进一步测试 RocksDB 内部功能，并评估其对性能的影响。</li><li>研究 Specter 漏洞的解决方案，并评估其对 Ceph 性能的影响。</li></ul></li><li><strong>代码简化</strong>： <ul><li>简化对象存储接口，以消除未读回调和锁。</li><li>将 Wall Clock Profiler 集成到 CBT 中。</li></ul></li></ul><h3 id="总结" tabindex="-1">总结： <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结：&quot;">​</a></h3><p>本次会议讨论了 Ceph 存储系统的最新进展、VPP 集成方案、性能优化策略和 Specter 漏洞影响评估。会议确定了行动计划，并推动了 Ceph 存储系统的进一步发展。</p>',18)])])}const h=e(t,[["render",a]]);export{c as __pageData,h as default};
